package com.glassos.launcher;
import android.app.*;
import android.os.*;
import android.content.*;
import android.content.pm.*;
import android.graphics.*;
import android.graphics.drawable.*;
import android.provider.Settings;
import android.view.*;
import android.widget.*;
import android.text.*;
import java.util.*;
public class MainActivity extends Activity {
 LinearLayout root; PackageManager pm; ArrayList<ResolveInfo> apps=new ArrayList<>(); boolean dark=false; String page="home"; float y;
 int ink(){return dark?0xffffffff:0xff15203c;} int glass(){return dark?0xcc202940:0xcceef3ff;}
 int d(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 GradientDrawable bg(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(d(r));g.setStroke(d(1),0x66ffffff);return g;}
 TextView text(String s,int size){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(ink());v.setGravity(Gravity.CENTER);return v;}
 LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
 LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(0);return l;}
 void show(String p){page=p;root=col();root.setPadding(d(15),d(36),d(15),d(22));root.setBackground(new GradientDrawable(GradientDrawable.Orientation.TL_BR,dark?new int[]{0xff101627,0xff38466a}:new int[]{0xffa6c5f9,0xfff1bdd9,0xffdfe9ff}));setContentView(root);}
 TextView action(String label,Runnable go){TextView v=text(label,17);v.setBackground(bg(glass(),22));v.setPadding(d(12),d(15),d(12),d(15));v.setOnClickListener(w->go.run());return v;}
 void heading(String s){LinearLayout r=row();TextView back=text("‹",30);r.addView(back,new LinearLayout.LayoutParams(d(45),d(56)));back.setOnClickListener(v->home());TextView t=text(s,25);r.addView(t,new LinearLayout.LayoutParams(0,d(56),1));root.addView(r);}
 void space(int v){root.addView(new View(this),new LinearLayout.LayoutParams(1,d(v)));}
 @Override public void onCreate(Bundle b){super.onCreate(b);pm=getPackageManager();dark=getPreferences(0).getBoolean("dark",false);refresh();home();}
 void refresh(){apps.clear();Intent intent=new Intent(Intent.ACTION_MAIN);intent.addCategory(Intent.CATEGORY_LAUNCHER);apps.addAll(pm.queryIntentActivities(intent,0));apps.removeIf(x->getPackageName().equals(x.activityInfo.packageName));apps.sort(Comparator.comparing(x->x.loadLabel(pm).toString().toLowerCase(Locale.ROOT)));}
 void launch(ResolveInfo a){try{Intent i=new Intent(Intent.ACTION_MAIN);i.addCategory(Intent.CATEGORY_LAUNCHER);i.setClassName(a.activityInfo.packageName,a.activityInfo.name);i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);startActivity(i);}catch(Exception e){Toast.makeText(this,"Unable to open app",0).show();}}
 void icons(LinearLayout dest,java.util.List<ResolveInfo> list){for(int i=0;i<list.size();i+=4){LinearLayout r=row();for(int j=i;j<i+4;j++){if(j>=list.size()){r.addView(new View(this),new LinearLayout.LayoutParams(0,d(104),1));continue;}ResolveInfo app=list.get(j);LinearLayout tile=col();tile.setGravity(Gravity.CENTER);ImageView image=new ImageView(this);image.setImageDrawable(app.loadIcon(pm));image.setPadding(d(6),d(6),d(6),d(6));tile.addView(image,new LinearLayout.LayoutParams(d(62),d(62)));TextView label=text(app.loadLabel(pm).toString(),11);label.setSingleLine();label.setEllipsize(TextUtils.TruncateAt.END);tile.addView(label);tile.setOnClickListener(v->launch(app));r.addView(tile,new LinearLayout.LayoutParams(0,d(106),1));}dest.addView(r);}}
 void home(){show("home");LinearLayout top=row();TextView time=text(new java.text.SimpleDateFormat("HH:mm",Locale.UK).format(new Date()),48);top.addView(time,new LinearLayout.LayoutParams(0,d(94),1));top.addView(action("☷",this::controls));root.addView(top);root.addView(text(new java.text.SimpleDateFormat("EEEE, d MMMM",Locale.UK).format(new Date()),18));space(20);
 LinearLayout widgets=row();TextView w=action("☀  Your day",this::library);widgets.addView(w,new LinearLayout.LayoutParams(0,d(120),1));TextView c=action("◉  Controls",this::controls);widgets.addView(c,new LinearLayout.LayoutParams(0,d(120),1));root.addView(widgets);space(18);
 LinearLayout grid=col();icons(grid,apps.subList(0,Math.min(12,apps.size())));root.addView(grid,new LinearLayout.LayoutParams(-1,0,1));root.addView(action("⌕  Search all apps",this::library));space(10);root.addView(action("⚙  GlassOS Settings",this::settings));}
 void library(){show("apps");heading("App Library");EditText field=new EditText(this);field.setSingleLine();field.setHint("Search apps");field.setBackground(bg(glass(),20));field.setPadding(d(16),d(10),d(16),d(10));root.addView(field);ScrollView scroll=new ScrollView(this);LinearLayout list=col();scroll.addView(list);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));Runnable update=()->{list.removeAllViews();ArrayList<ResolveInfo> found=new ArrayList<>();String q=field.getText().toString().toLowerCase(Locale.ROOT);for(ResolveInfo a:apps)if(a.loadLabel(pm).toString().toLowerCase(Locale.ROOT).contains(q))found.add(a);icons(list,found);};field.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){update.run();}public void afterTextChanged(Editable e){}});update.run();}
 void item(String title,Runnable go){root.addView(action(title,go),new LinearLayout.LayoutParams(-1,d(68)));space(12);}
 void controls(){show("controls");heading("Control Centre");item("◉  Wi-Fi",()->startActivity(new Intent(Settings.ACTION_WIFI_SETTINGS)));item("ᛒ  Bluetooth",()->startActivity(new Intent(Settings.ACTION_BLUETOOTH_SETTINGS)));item("♫  Sound",()->startActivity(new Intent(Settings.ACTION_SOUND_SETTINGS)));item("☀  Display",()->startActivity(new Intent(Settings.ACTION_DISPLAY_SETTINGS)));root.addView(text("Brightness",18));SeekBar brightness=new SeekBar(this);brightness.setMax(255);brightness.setProgress(150);brightness.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean user){if(user){WindowManager.LayoutParams a=getWindow().getAttributes();a.screenBrightness=Math.max(.01f,p/255f);getWindow().setAttributes(a);}}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});root.addView(brightness);item("▣  Notifications",this::notifications);item("⚙  Theme settings",this::settings);}
 void notifications(){show("notifications");heading("Notifications");if(GlassNotificationListener.current==null){item("Allow notification access",()->startActivity(new Intent(Settings.ACTION_NOTIFICATION_LISTENER_SETTINGS)));return;}java.util.List<android.service.notification.StatusBarNotification> items=GlassNotificationListener.recent();ScrollView sv=new ScrollView(this);LinearLayout l=col();sv.addView(l);root.addView(sv);if(items.isEmpty())l.addView(text("No notifications",20));for(android.service.notification.StatusBarNotification n:items){CharSequence title=n.getNotification().extras.getCharSequence(Notification.EXTRA_TITLE);CharSequence msg=n.getNotification().extras.getCharSequence(Notification.EXTRA_TEXT);TextView t=action((title==null?n.getPackageName():title.toString())+"\n"+(msg==null?"":msg.toString()),()->{try{if(n.getNotification().contentIntent!=null)n.getNotification().contentIntent.send();}catch(Exception ignored){}});l.addView(t);}}
 void settings(){show("settings");heading("GlassOS Settings");item("Appearance: "+(dark?"Dark":"Light"),()->{dark=!dark;getPreferences(0).edit().putBoolean("dark",dark).apply();settings();});item("Choose default Home app",()->startActivity(new Intent(Settings.ACTION_HOME_SETTINGS)));item("Notification access",()->startActivity(new Intent(Settings.ACTION_NOTIFICATION_LISTENER_SETTINGS)));item("System settings",()->startActivity(new Intent(Settings.ACTION_SETTINGS)));root.addView(text("GlassOS v0.1 • iOS-inspired Android launcher. Protected Samsung screens and third-party apps remain unchanged.",14));}
 @Override public void onBackPressed(){if("home".equals(page))super.onBackPressed();else home();}
}